import { Activity, ArrowLeft, ArrowRight, BarChart3, Bell, Bot, Check, ChevronDown, Clock3, Crosshair, Database, ExternalLink, Factory, Globe2, Info, Landmark, LockKeyhole, Newspaper, RefreshCw, Shield, SlidersHorizontal, Upload, UsersRound } from 'lucide-react';
import { lazy, Suspense, useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { adminRequest, getCollection, getDetail, getMarketHistory, getStatus, getSummary, request } from './api';
import { Badge, Empty, ErrorState, FavoriteButton, Loading, Metric, Pagination, Panel, RowLink, SearchBox, SectionTitle, SourceMeta } from './components';
import { useRemote } from './hooks';
import { RESOURCES, type Collection, type ResourceKey, type Row, type Source, type Status } from './types';
import { age, date, displayName, normalizedData, number, readFavorites, safeUrl, saveFavorites, sourceState, text } from './utils';
import { CoveragePanel } from './coverage';
import type { OperationsHealth } from '../shared/operations';
import { FollowButton } from './follow';
import { ActivityPanel } from './activity';
import { isHistoryResource } from '../shared/history';
import { RelationsExplorer } from './intelligence';
import type { RelationResource } from '../shared/intelligence';
import { calculateEconomics, compareInvestment, compareProductionChain, priceSensitivity } from '../shared/economics';

// Charts load on demand: the dashboard and directories never pull the charting library.
const HistoryExplorer = lazy(() => import('./history').then(module => ({ default: module.HistoryExplorer })));
const MarketAreaChart = lazy(() => import('./market-chart'));
const paths: Record<ResourceKey, string> = { countries: '/paises', players: '/jugadores', parties: '/partidos', 'military-units': '/unidades', battles: '/batallas', companies: '/empresas', articles: '/articulos', events: '/alertas', alerts: '/alertas', regions: '/regiones',elections:'/elecciones',governments:'/gobiernos' };
const defaultFilters = { q: '', country: '', sort: 'updated_at', order: 'desc', page: 1, limit: 20 };
const sortOptions = [{ value: 'updated_at', label: 'Última actualización' }, { value: 'name', label: 'Nombre' }, { value: 'level', label: 'Nivel' }, { value: 'experience', label: 'Experiencia' }, { value: 'published_at', label: 'Publicación' }];
const publicFields = new Set(['id', 'name', 'title', 'country_id', 'level', 'experience', 'author_id', 'published_at', 'first_seen', 'updated_at', 'source_url', 'price', 'captured_at', 'item_id']);
const fieldLabels: Record<string, string> = { id: 'ID', name: 'Nombre', title: 'Título', country_id: 'País', level: 'Nivel', experience: 'Experiencia', author_id: 'Autor', published_at: 'Publicado', first_seen: 'Primera captura', updated_at: 'Actualizado', price: 'Precio', captured_at: 'Capturado', item_id: 'Artículo', members: 'Miembros', damage: 'Daño', region_id: 'Región', status: 'Estado', description: 'Descripción', language: 'Idioma', views: 'Vistas', likes: 'Me gusta' };

function Notice({ children, tone = 'info' }: { children: React.ReactNode; tone?: 'info' | 'warn' }) { return <div className={`notice ${tone}`}><Info size={17} /><span>{children}</span></div>; }
function EntityList({ items, base, empty = 'Sin datos capturados.' }: { items: Row[]; base: string; empty?: string }) {
  if (!items.length) return <Empty detail={empty} />;
  return <div className="entity-list">{items.map((row, index) => <RowLink key={`${row.id ?? row.item_id ?? index}`} row={row} base={base} subtitle={date(row.published_at ?? row.updated_at ?? row.captured_at)} />)}</div>;
}

export function Dashboard() {
  const remote = useRemote(getSummary, 'summary', 90_000);
  const data = remote.data;
  return <>
    <SectionTitle eyebrow="OPERACIONES · VISTA GLOBAL" title="Centro de mando" description="Señales verificables de las fuentes públicas conectadas a WINT." action={<button className="btn" onClick={remote.reload} disabled={remote.refreshing}><RefreshCw size={15} className={remote.refreshing ? 'spin' : ''} /> Actualizar</button>} />
    {remote.error && <ErrorState error={remote.error} onRetry={remote.reload} hasData={!!data} />}
    {remote.loading && !data ? <Loading /> : data && <>
      <div className="metric-grid"><Metric label="Jugadores registrados" value={number(data.totals?.players)} hint="perfiles capturados" icon={<UsersRound size={17} />} /><Metric label="Países" value={number(data.totals?.countries)} hint="registros territoriales" icon={<Globe2 size={17} />} /><Metric label="Unidades militares" value={number(data.totals?.['military-units'] ?? data.totals?.military_units)} hint="unidades conocidas" icon={<Shield size={17} />} /><Metric label="Artículos" value={number(data.totals?.articles)} hint="hemeroteca indexada" icon={<Newspaper size={17} />} /></div>
      <div className="dashboard-grid"><Panel title="Acontecimientos recientes" action={<Link to="/alertas" className="text-link">Ver todos <ArrowRight size={14} /></Link>}><EntityList items={data.recentEvents ?? []} base="/alertas" empty="Todavía no se han detectado acontecimientos verificables." /></Panel><Panel title="Batallas activas" action={<Link to="/batallas" className="text-link">Abrir panel <ArrowRight size={14} /></Link>}><EntityList items={data.activeBattles ?? []} base="/batallas" empty="No hay batallas activas confirmadas en las fuentes conectadas." /></Panel><Panel title="Prensa reciente" action={<Link to="/articulos" className="text-link">Hemeroteca <ArrowRight size={14} /></Link>}><EntityList items={data.recentArticles ?? []} base="/articulos" empty="Aún no hay artículos capturados." /></Panel><Panel title="Mercados observados" action={<Link to="/mercados" className="text-link">Terminal <ArrowRight size={14} /></Link>}>{(data.marketPrices ?? []).length ? <div className="market-mini">{data.marketPrices.slice(0, 6).map((row, index) => <div key={`${row.id ?? index}`}><span>{displayName(row)}</span><strong>{number(row.price, 3)}</strong></div>)}</div> : <Empty detail="No hay capturas de precios verificadas." />}</Panel></div>
      <Panel title="Estado de captación" action={<Link to="/estado" className="text-link">Detalle de fuentes <ArrowRight size={14} /></Link>}><div className="source-grid">{(data.sources ?? []).length ? data.sources.filter(source => source.enabled).map(source => <div className="source-card" key={source.id}><div><strong>{source.id}</strong><Badge tone={sourceState(source).tone}>{sourceState(source).label}</Badge></div><small>Última captura: {date(source.last_success)} · {age(source.last_success)}</small></div>) : <Empty detail="No hay fuentes configuradas en el registro." />}</div></Panel>
      <div className="dashboard-footnote">Resumen generado {date(data.timestamp)}. Las cifras reflejan únicamente registros almacenados en WINT.{data.coverage && <> Censo en curso: {number(data.coverage.countries_started)} de {number(data.totals.countries)} países recorridos; {number(data.coverage.countries_completed ?? 0)} con un recorrido completo.</>}</div>
    </>}
  </>;
}

function columnsFor(resource: ResourceKey): { key: string; label: string }[] {
  if (resource === 'players') return [{ key: 'name', label: 'Jugador' }, { key: 'country_id', label: 'País' }, { key: 'level', label: 'Nivel' }, { key: 'experience', label: 'Experiencia' }, { key: 'updated_at', label: 'Actualización' }];
  if (resource === 'articles') return [{ key: 'title', label: 'Artículo' }, { key: 'author_id', label: 'Autor' }, { key: 'published_at', label: 'Publicación' }, { key: 'updated_at', label: 'Captura' }];
  if (resource === 'battles') return [{ key: 'name', label: 'Batalla' }, { key: 'country_id', label: 'País' }, { key: 'updated_at', label: 'Actualización' }];
  return [{ key: 'name', label: RESOURCES[resource].singular }, { key: 'country_id', label: 'País' }, { key: 'updated_at', label: 'Actualización' }];
}
function cell(row: Row, key: string): React.ReactNode {
  const value = row[key];
  if (key.endsWith('_at')) return <span title={date(value)}>{age(value)}</span>;
  if (key === 'level' || key === 'experience') return number(value);
  return text(value);
}

export function Directory({ resource }: { resource: ResourceKey }) {
  const config = RESOURCES[resource];
  const [params, setParams] = useSearchParams();
  const [draft, setDraft] = useState(params.get('q') ?? '');
  const q = params.get('q') ?? '';
  const country = params.get('country') ?? '';
  const sort = params.get('sort') ?? defaultFilters.sort;
  const order = params.get('order') ?? defaultFilters.order;
  const page = Math.max(1, Number(params.get('page') ?? 1) || 1);
  const limit = 20;
  useEffect(() => { setDraft(q); }, [q]);
  useEffect(() => { const timer = window.setTimeout(() => { if (draft !== q) setParams(current => { const next = new URLSearchParams(current); draft ? next.set('q', draft) : next.delete('q'); next.delete('page'); return next; }); }, 320); return () => window.clearTimeout(timer); }, [draft, q, setParams]);
  const query = new URLSearchParams({ page: String(page), limit: String(limit), sort, order });
  if (q) query.set('q', q);
  if (country) query.set('country', country);
  const advancedFilters=resource==='players'?['party','unit','minLevel','maxLevel','activity']:resource==='articles'?['language','author','category','from','to']:[];
  for(const key of advancedFilters){const value=params.get(key);if(value)query.set(key,value);}
  const remote = useRemote(() => getCollection(config.endpoint, query), `${resource}:${query}`, 90_000);
  const update = (key: string, value: string) => setParams(current => { const next = new URLSearchParams(current); value ? next.set(key, value) : next.delete(key); if (key !== 'page') next.delete('page'); return next; });
  const columns = columnsFor(resource);
  const availableSorts = sortOptions.filter(option => option.value === 'name' || option.value === 'updated_at' || (resource === 'players' && ['level', 'experience'].includes(option.value)) || (resource === 'articles' && option.value === 'published_at'));
  return <>
    <SectionTitle eyebrow="EXPLORADOR DE DATOS" title={config.title} description={config.description} action={<button className="btn" onClick={remote.reload} disabled={remote.refreshing}><RefreshCw size={15} className={remote.refreshing ? 'spin' : ''} /> Actualizar</button>} />
    <div className="toolbar"><SearchBox value={draft} onChange={setDraft} placeholder={resource === 'articles' ? 'Buscar artículos…' : `Buscar ${config.title.toLowerCase()}…`} /><label className="input-wrap"><Globe2 size={15} /><input value={country} onChange={event => update('country', event.target.value)} placeholder="ID de país" aria-label="Filtrar por ID de país" /></label><label className="select-wrap"><SlidersHorizontal size={15} /><select value={sort} onChange={event => update('sort', event.target.value)} aria-label="Ordenar por">{availableSorts.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select><ChevronDown size={13} /></label><button className="btn sort-direction" onClick={() => update('order', order === 'asc' ? 'desc' : 'asc')} title={order === 'asc' ? 'Ascendente' : 'Descendente'}>{order === 'asc' ? '↑ Asc.' : '↓ Desc.'}</button></div>
    {advancedFilters.length>0 && <details className="directory-advanced"><summary>Filtros avanzados</summary><div className="history-controls">{advancedFilters.map(key=><label className="form-field" key={key}><span>{({party:'ID de partido',unit:'ID de unidad',minLevel:'Nivel mínimo',maxLevel:'Nivel máximo',activity:'Actividad observable',language:'Idioma',author:'ID de autor',category:'Categoría',from:'Desde',to:'Hasta'} as Record<string,string>)[key]}</span>{key==='activity'?<select value={params.get(key) ?? ''} onChange={event=>update(key,event.target.value)}><option value="">Todas</option><option value="recent">Conexión observada en 7 días</option><option value="inactive">Última conexión anterior a 7 días</option><option value="unknown">Sin fecha observada</option></select>:<input type={key==='from'||key==='to'?'date':key.endsWith('Level')?'number':'text'} min={key.endsWith('Level')?0:undefined} maxLength={100} value={params.get(key) ?? ''} onChange={event=>update(key,event.target.value)} />}</label>)}</div>{resource==='players' && <p className="analysis-note">La fecha de conexión es una observación pública; no demuestra abandono ni actividad actual. Los límites de nivel los eliges tú.</p>}</details>}
    {remote.error && <ErrorState error={remote.error} onRetry={remote.reload} hasData={!!remote.data} />}
    <Panel title={`${config.title} ${remote.data ? `· ${number(remote.data.total)}` : ''}`} action={<SourceMeta source={remote.data?.source} updatedAt={remote.data?.source?.last_success} />}>
      {remote.loading && !remote.data ? <Loading /> : remote.data && remote.data.items.length ? <><div className="table-scroll" tabIndex={0} role="region" aria-label="Tabla desplazable"><table className="data-table"><thead><tr>{columns.map(column => <th key={column.key}>{column.label}</th>)}<th>Fuente</th><th aria-label="Abrir" /></tr></thead><tbody>{remote.data.items.map((row, index) => <tr key={`${row.id ?? index}`}><td><Link className="table-name" to={`${paths[resource]}/${encodeURIComponent(text(row.id, ''))}`}>{displayName(row)}</Link><small>ID {text(row.id)}</small></td>{columns.slice(1).map(column => <td key={column.key}>{cell(row, column.key)}</td>)}<td>{safeUrl(row.source_url) ? <a className="source-link" href={safeUrl(row.source_url)!} target="_blank" rel="noopener noreferrer">Original <ExternalLink size={12} /></a> : <span className="muted">—</span>}</td><td><Link className="row-open" to={`${paths[resource]}/${encodeURIComponent(text(row.id, ''))}`} aria-label={`Abrir ${displayName(row)}`}><ArrowRight size={15} /></Link></td></tr>)}</tbody></table></div><Pagination page={page} total={remote.data.total} limit={limit} onPage={value => update('page', String(value))} /></> : remote.data ? <Empty title={q || country ? 'Sin resultados' : 'Todavía no hay registros'} detail={q || country ? 'Prueba con otra búsqueda o filtro.' : 'La fuente aún no ha entregado registros para este módulo.'} /> : null}
    </Panel>
    <p className="footnote">Los registros aparecen cuando el recolector confirma y almacena datos públicos. La ausencia de registros no implica ausencia de actividad en WarEra.</p>
  </>;
}

function DetailFields({ row }: { row: Row }) {
  const data = normalizedData(row);
  const merged = { ...data, ...row };
  const entries = Object.entries(merged).filter(([key, value]) => key !== 'data' && key !== 'source_url' && (publicFields.has(key) || (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean')) && value !== null && value !== '' && value !== undefined).slice(0, 40);
  return <div className="detail-fields">{entries.map(([key, value]) => <div key={key}><span>{fieldLabels[key] ?? key.replaceAll('_', ' ')}</span><strong>{key.endsWith('_at') ? date(value) : text(value)}</strong></div>)}</div>;
}
export function DetailPage({ resource }: { resource: ResourceKey }) {
  const { id = '' } = useParams();
  const config = RESOURCES[resource];
  const remote = useRemote(() => getDetail(config.endpoint, id), `${resource}:${id}`, 90_000);
  const row = remote.data?.item;
  return <><Link to={paths[resource]} className="back-link"><ArrowLeft size={15} /> Volver a {config.title.toLowerCase()}</Link>
    <SectionTitle eyebrow={`${config.singular.toUpperCase()} · ID ${id}`} title={row ? displayName(row) : config.singular} description={row ? 'Ficha de datos públicos capturados por WINT.' : 'Consultando registro…'} action={<div className="toolbar-actions">{row && <FollowButton resource={resource} row={row} name={displayName(row)} />}<button className="btn" onClick={remote.reload}><RefreshCw size={15} /> Actualizar</button></div>} />
    {remote.error && <ErrorState error={remote.error} onRetry={remote.reload} hasData={!!row} />}{remote.loading && !row ? <Loading /> : row ? <><div className="detail-layout"><Panel title="Datos registrados"><DetailFields row={row} /><SourceMeta source={remote.data?.source} updatedAt={row.updated_at ?? row.published_at} sourceUrl={row.source_url} /></Panel><Panel title="Procedencia e historial"><div className="detail-summary"><span>Primera captura</span><strong>{date(row.first_seen)}</strong></div><div className="detail-summary"><span>Última actualización</span><strong>{date(row.updated_at)}</strong></div><div className="detail-summary"><span>Instantáneas disponibles</span><strong>{number(remote.data?.history?.length ?? 0)}</strong></div>{safeUrl(row.source_url) && <a className="btn primary detail-source" href={safeUrl(row.source_url)!} target="_blank" rel="noopener noreferrer">Abrir fuente original <ExternalLink size={14} /></a>}</Panel></div>{['players','parties','military-units','companies','countries','elections','governments'].includes(resource) && <RelationsExplorer resource={resource as RelationResource} id={id} />}{isHistoryResource(resource) && <Suspense fallback={<Loading label="Cargando histórico…" />}><HistoryExplorer resource={resource} id={id} name={displayName(row)} /></Suspense>}<Panel title="Historial registrado">{remote.data?.history?.length ? <div className="history-list">{remote.data.history.map((entry, index) => <div key={index}><span className="history-dot" /><strong>{date(entry.captured_at ?? entry.updated_at)}</strong><span>{Object.entries(entry).filter(([key]) => !['id','data','captured_at','updated_at'].includes(key)).slice(0, 4).map(([key, value]) => `${fieldLabels[key] ?? key}: ${text(value)}`).join(' · ') || 'Captura registrada'}</span></div>)}</div> : <Empty title="Sin historial disponible" detail="WINT mostrará las variaciones cuando existan capturas sucesivas verificadas." />}</Panel>{resource === 'countries' && <CountryConnections id={id} />}</> : null}</>;
}

// Everything WINT captured for one country, one click from its record. Each
// block reads the existing public list endpoint filtered by country_id.
const COUNTRY_BLOCKS: { resource: ResourceKey; sort: string; order: 'asc' | 'desc' }[] = [
  { resource: 'players', sort: 'level', order: 'desc' }, { resource: 'parties', sort: 'updated_at', order: 'desc' },
  { resource: 'military-units', sort: 'updated_at', order: 'desc' }, { resource: 'governments', sort: 'updated_at', order: 'desc' },
  { resource: 'elections', sort: 'updated_at', order: 'desc' }, { resource: 'battles', sort: 'updated_at', order: 'desc' },
  { resource: 'companies', sort: 'updated_at', order: 'desc' }, { resource: 'regions', sort: 'name', order: 'asc' },
  { resource: 'articles', sort: 'published_at', order: 'desc' }, { resource: 'events', sort: 'updated_at', order: 'desc' },
];
function CountryConnections({ id }: { id: string }) {
  const remote = useRemote(() => Promise.all(COUNTRY_BLOCKS.map(block => getCollection(RESOURCES[block.resource].endpoint,
    new URLSearchParams({ country: id, page: '1', limit: '5', sort: block.sort, order: block.order })).catch(() => null))), `country-connections:${id}`);
  return <section className="section-gap" aria-labelledby="country-connections-title">
    <div className="section-title"><div><span className="eyebrow">FICHA CONECTADA</span><h2 id="country-connections-title">Todo lo capturado de este país</h2><p>Registros observados por WINT con este país asignado. No son totales de WarEra.</p></div><Link to={`/estrategia?country=${encodeURIComponent(id)}`} className="btn"><BarChart3 size={15} /> Informe estratégico</Link></div>
    {remote.loading && !remote.data ? <Loading label="Reuniendo registros del país…" /> : <div className="dashboard-grid">{COUNTRY_BLOCKS.map((block, index) => {
      const data = remote.data?.[index], config = RESOURCES[block.resource], base = paths[block.resource];
      return <Panel key={block.resource} title={`${config.title}${data ? ` · ${number(data.total)}` : ''}`} action={data && data.total > 0 ? <Link to={`${base}?country=${encodeURIComponent(id)}`} className="text-link">Ver todos <ArrowRight size={14} /></Link> : undefined}>
        {data ? <EntityList items={data.items} base={base} empty={`Sin ${config.title.toLowerCase()} capturados con este país.`} /> : <Empty detail="No se pudo consultar este bloque." />}</Panel>;
    })}</div>}
    <div className="section-gap"><ActivityPanel countryId={id} /></div>
  </section>;
}

export function WorldPage() {
  const countries = useRemote(() => getCollection('/api/countries', new URLSearchParams({ page: '1', limit: '50', sort: 'name', order: 'asc' })), 'world-countries', 90_000);
  const regions = useRemote(() => getCollection('/api/regions', new URLSearchParams({ page: '1', limit: '10', sort: 'name', order: 'asc' })), 'world-regions', 90_000);
  return <><SectionTitle eyebrow="INTELIGENCIA TERRITORIAL" title="Mundo WarEra" description="Explora los países y regiones confirmados en WINT." /><Notice>El mapa histórico interactivo y el control territorial requieren capturas geográficas verificadas. Mientras tanto, consulta el directorio real de países y regiones.</Notice><div className="dashboard-grid"><Panel title="Países registrados" action={<Link to="/paises" className="text-link">Directorio <ArrowRight size={14} /></Link>}>{countries.loading ? <Loading /> : countries.error ? <ErrorState error={countries.error} onRetry={countries.reload} /> : <EntityList items={countries.data?.items ?? []} base="/paises" />}</Panel><Panel title="Regiones capturadas">{regions.loading ? <Loading /> : regions.error ? <ErrorState error={regions.error} onRetry={regions.reload} /> : regions.data?.items.length ? <div className="simple-list">{regions.data.items.map(row => <div key={text(row.id)}><strong>{displayName(row)}</strong><span>País {text(row.country_id)}</span></div>)}</div> : <Empty />}</Panel></div></>;
}

export function MarketPage() {
  const [params, setParams] = useSearchParams();
  const selected = params.get('item') ?? '';
  const [search, setSearch] = useState('');
  const [draft, setDraft] = useState('');
  const [page, setPage] = useState(1);
  useEffect(() => { const timer = window.setTimeout(() => { setSearch(draft); setPage(1); }, 320); return () => window.clearTimeout(timer); }, [draft]);
  const list = useRemote(() => getCollection('/api/markets/prices', new URLSearchParams({ page: String(page), limit: '12', q: search, sort: 'price', order: 'desc' })), `markets:${page}:${search}`, 90_000);
  const history = useRemote(() => selected ? getMarketHistory(selected) : Promise.resolve({ items: [] as Row[], source: null as Source | null }), `market-history:${selected}`, selected ? 90_000 : 0);
  const values = useMemo(() => (history.data?.items ?? []).map(row => ({ time: date(row.captured_at), price: Number(row.price) })).filter(row => Number.isFinite(row.price)), [history.data]);
  const chosen = list.data?.items.find(row => text(row.item_id ?? row.id) === selected);
  return <><SectionTitle eyebrow="INTELIGENCIA ECONÓMICA" title="Economía y mercados" description="Precios capturados y series históricas disponibles en WINT." action={<Link to="/industria" className="btn primary"><Factory size={15} /> Simulador industrial</Link>} />
    <div className="analysis-note"><Link to="/mercados/ordenes">Ver órdenes públicas observadas</Link> · <Link to="/empresas">Explorar empresas capturadas</Link> · <Link to="/simulador">Abrir el simulador manual</Link></div>
    <Notice>Los precios representan capturas observadas. Sin órdenes y volumen verificados, WINT no calcula liquidez ni recomienda transacciones.</Notice>
    <div className="market-layout"><Panel title="Precios observados" action={<Badge tone={sourceState(list.data?.source).tone}>{sourceState(list.data?.source).label}</Badge>}><div className="panel-toolbar"><SearchBox value={draft} onChange={setDraft} placeholder="Buscar producto…" /></div>{list.error && <ErrorState error={list.error} onRetry={list.reload} hasData={!!list.data} />}{list.loading && !list.data ? <Loading /> : list.data?.items.length ? <><div className="market-list">{list.data.items.map(row => { const id = text(row.item_id ?? row.id, ''); return <button key={`${row.id ?? id}`} className={`market-row ${selected === id ? 'active' : ''}`} onClick={() => setParams(id ? { item: id } : {})}><span><strong>{displayName(row)}</strong><small>{date(row.captured_at)}</small></span><span className="market-price">{number(row.price, 4)}</span></button>; })}</div><Pagination page={page} total={list.data.total} limit={12} onPage={setPage} /></> : list.data ? <Empty title={search ? 'Sin productos coincidentes' : 'Sin precios capturados'} detail={search ? 'Prueba otra búsqueda.' : 'Aún no se han capturado precios públicos.'} /> : null}</Panel>
    <Panel title={chosen ? `Histórico · ${displayName(chosen)}` : 'Histórico de precios'} action={selected && <SourceMeta source={history.data?.source} />}>{!selected ? <Empty title="Selecciona un producto" detail="Elige un precio observado para consultar capturas anteriores." /> : history.error ? <ErrorState error={history.error} onRetry={history.reload} /> : history.loading ? <Loading /> : values.length >= 2 ? <><div className="chart-wrap"><Suspense fallback={<Loading label="Cargando gráfico…" />}><MarketAreaChart values={values} /></Suspense></div><div className="chart-caption">{values.length} capturas · Última observación {values.at(-1)?.time}</div></> : history.data ? <Empty title="Histórico insuficiente" detail="Se necesitan al menos dos capturas reales para trazar una evolución." /> : null}</Panel></div>
    {selected && <Suspense fallback={<Loading label="Cargando histórico…" />}><HistoryExplorer resource="markets" id={selected} name={chosen ? displayName(chosen) : selected} /></Suspense>}
  </>;
}

type SimInputs = { type: string; level: number; automation: number; capacity: number; rawCost: number; wage: number; tax: number; sellPrice: number; investment: number; unitsPerWorker: number; upgradeCost: number; upgradeCapacity: number };
const initialSim: SimInputs = { type: 'Manufactura', level: 1, automation: 0, capacity: 100, rawCost: 1, wage: 30, tax: 10, sellPrice: 2, investment: 1000, unitsPerWorker: 50, upgradeCost: 500, upgradeCapacity: 25 };
function calculate(i: SimInputs) {
  const capacity = Math.max(0, i.capacity);
  const workers = i.unitsPerWorker > 0 ? Math.ceil(capacity / (i.unitsPerWorker * (1 + Math.max(0, i.automation) / 100))) : 0;
  const labor = workers * i.wage;
  const base = { unitsPerDay: capacity, salePricePerUnit: i.sellPrice, materialsCostPerUnit: i.rawCost, wagesPerDay: labor, fixedCostPerDay: 0, taxRate: Math.min(100, Math.max(0, i.tax)) / 100, investment: i.investment };
  const nextCapacity = capacity + Math.max(0, i.upgradeCapacity);
  const upgradeWorkers = i.unitsPerWorker > 0 ? Math.ceil(nextCapacity / (i.unitsPerWorker * (1 + Math.max(0, i.automation) / 100))) : 0;
  const upgrade = { ...base, unitsPerDay: nextCapacity, wagesPerDay: upgradeWorkers * i.wage, investment: i.investment + i.upgradeCost };
  const result = calculateEconomics(base);
  const comparison = compareInvestment(base, upgrade);
  const sensitivity = priceSensitivity(base, [-0.1, 0, 0.1]);
  return { workers, labor, raw: result.materialsCostPerDay, revenue: result.revenuePerDay, taxAmount: result.taxesPerDay, profit: result.netProfitPerDay, unitCost: result.unitCost ?? NaN, margin: result.revenuePerDay ? result.grossMarginPerUnit / i.sellPrice * 100 : NaN, roi: result.roiPerDay === null ? NaN : result.roiPerDay * 100, payback: result.paybackDays ?? NaN, upgradeProfit: comparison.upgrade.netProfitPerDay, incrementalProfit: comparison.marginalProfitPerDay, upgradePayback: comparison.marginalPaybackDays ?? NaN, sensitivity };
}
function Simulator() {
  const [inputs, setInputs] = useState<SimInputs>(initialSim);
  const output = useMemo(() => calculate(inputs), [inputs]);
  const change = (key: keyof SimInputs, value: string) => setInputs(current => ({ ...current, [key]: key === 'type' ? value : Math.max(0, Number(value) || 0) }));
  const fields: { key: keyof SimInputs; label: string; unit?: string; min?: number; step?: string }[] = [
    { key: 'level', label: 'Nivel de empresa', min: 1 }, { key: 'automation', label: 'Automatización asumida', unit: '%', min: 0 }, { key: 'capacity', label: 'Producción diaria', unit: 'uds.', min: 0 }, { key: 'unitsPerWorker', label: 'Unidades por trabajador y día', unit: 'uds.', min: 0 },
    { key: 'rawCost', label: 'Materia prima por unidad', unit: 'moneda', min: 0, step: '0.01' }, { key: 'wage', label: 'Salario diario por trabajador', unit: 'moneda', min: 0, step: '0.01' }, { key: 'tax', label: 'Impuesto sobre ingresos', unit: '%', min: 0, step: '0.1' }, { key: 'sellPrice', label: 'Precio de venta por unidad', unit: 'moneda', min: 0, step: '0.01' },
    { key: 'investment', label: 'Inversión inicial', unit: 'moneda', min: 0, step: '0.01' }, { key: 'upgradeCost', label: 'Coste de ampliación', unit: 'moneda', min: 0, step: '0.01' }, { key: 'upgradeCapacity', label: 'Capacidad extra diaria', unit: 'uds.', min: 0 },
  ];
  return <><Notice>Escenario hipotético. Todos los valores iniciales son supuestos editables del usuario; ninguna cifra ni fórmula está confirmada como mecánica de WarEra.</Notice><div className="sim-layout"><Panel title="Supuestos del escenario"><label className="form-field"><span>Tipo de empresa</span><select value={inputs.type} onChange={event => change('type', event.target.value)}><option>Manufactura</option><option>Extracción</option><option>Servicios</option><option>Otro</option></select></label><div className="form-grid">{fields.map(field => <label className="form-field" key={field.key}><span>{field.label}{field.unit && <small> · {field.unit}</small>}</span><input type="number" inputMode="decimal" min={field.min} step={field.step ?? '1'} value={inputs[field.key]} onChange={event => change(field.key, event.target.value)} /></label>)}</div></Panel><Panel title="Resultado estimado"><div className="sim-result"><span>Beneficio neto diario estimado</span><strong className={output.profit >= 0 ? 'positive' : 'negative'}>{number(output.profit, 2)}</strong><small>unidades monetarias del escenario</small></div><div className="sim-metrics"><div><span>Coste unitario</span><strong>{number(output.unitCost, 3)}</strong></div><div><span>Margen bruto</span><strong>{number(output.margin, 1)}%</strong></div><div><span>Retorno diario</span><strong>{number(output.roi, 2)}%</strong></div><div><span>Amortización</span><strong>{Number.isFinite(output.payback) ? `${number(output.payback, 1)} días` : 'No recuperable'}</strong></div><div><span>Trabajadores necesarios</span><strong>{number(output.workers)}</strong></div><div><span>Beneficio extra al ampliar</span><strong>{number(output.incrementalProfit, 2)}</strong></div><div><span>Amortización ampliación</span><strong>{Number.isFinite(output.upgradePayback) ? `${number(output.upgradePayback, 1)} días` : 'No recuperable'}</strong></div></div><div className="formula"><strong>Fórmula reproducible</strong><p>Trabajadores = techo(capacidad ÷ [unidades por trabajador × (1 + automatización / 100)]). Coste = producción × materia prima + trabajadores × salario + ingresos × impuesto. Beneficio neto = ingresos − coste. Ampliación: se recalcula con capacidad adicional.</p><p>El nivel y tipo identifican el escenario; no alteran las fórmulas hasta verificar reglas oficiales del juego.</p></div><div className="sensitivity"><strong>Sensibilidad al precio de venta</strong>{output.sensitivity.map(item => <div key={item.change}><span>{item.change < 0 ? '−10 %' : item.change > 0 ? '+10 %' : 'Actual'}</span><strong className={item.profitPerDay >= 0 ? 'positive' : 'negative'}>{number(item.profitPerDay, 2)}</strong></div>)}</div></Panel></div><ChainComparison /></>;
}

function ChainComparison() {
  const [values, setValues] = useState({ rawUnits: 100, rawSalePrice: 1, outputUnitsPerRawUnit: 1, outputSalePrice: 2, processingCostPerRawUnit: 0.6, extraFixedCost: 20, taxRate: 10 });
  const result = compareProductionChain({ ...values, taxRate: Math.min(100, Math.max(0, values.taxRate)) / 100 });
  const fields = [{ key: 'rawUnits', label: 'Unidades de materia prima' }, { key: 'rawSalePrice', label: 'Precio unitario sin transformar' }, { key: 'outputUnitsPerRawUnit', label: 'Rendimiento por unidad' }, { key: 'outputSalePrice', label: 'Precio del producto final' }, { key: 'processingCostPerRawUnit', label: 'Coste de proceso por unidad' }, { key: 'extraFixedCost', label: 'Coste fijo de transformación' }, { key: 'taxRate', label: 'Impuesto sobre ingresos (%)' }] as const;
  return <Panel title="Cadena productiva · vender o transformar" className="section-gap"><div className="chain-layout"><div className="form-grid">{fields.map(field => <label className="form-field" key={field.key}><span>{field.label}</span><input type="number" min="0" step="0.01" value={values[field.key]} onChange={event => setValues(current => ({ ...current, [field.key]: Math.max(0, Number(event.target.value) || 0) }))} /></label>)}</div><div className="chain-result"><div><span>Venta de materia prima</span><strong>{number(result.sellRawProfit, 2)}</strong></div><div><span>Transformación y venta</span><strong>{number(result.transformProfit, 2)}</strong></div><div><span>Ventaja de transformar</span><strong className={result.transformationAdvantage >= 0 ? 'positive' : 'negative'}>{number(result.transformationAdvantage, 2)}</strong></div><p>Supuestos editables: beneficio de venta directa = unidades × precio × (1 − impuesto). Beneficio transformando = unidades × rendimiento × precio final × (1 − impuesto) − proceso − coste fijo.</p></div></div></Panel>;
}
export function IndustryPage() {
  const companies = useRemote(() => getCollection('/api/companies', new URLSearchParams({ page: '1', limit: '8', sort: 'updated_at', order: 'desc' })), 'companies-overview', 90_000);
  return <><SectionTitle eyebrow="ANÁLISIS INDUSTRIAL" title="Empresas e industria" description="Empresas observadas y cálculo económico con supuestos transparentes." /><div className="tabs"><a href="#empresas">Empresas registradas</a><a href="#simulador">Simulador</a></div><div id="empresas"><Panel title="Empresas capturadas" action={<SourceMeta source={companies.data?.source} />}>{companies.loading ? <Loading /> : companies.error ? <ErrorState error={companies.error} onRetry={companies.reload} /> : <EntityList items={companies.data?.items ?? []} base="/empresas" empty="La fuente de empresas aún no ha entregado datos verificables." />}</Panel></div><div id="simulador" className="section-gap"><SectionTitle eyebrow="ESCENARIO EDITABLE" title="Simulador industrial" description="Calcula costes, margen y amortización con tus propias hipótesis." /><Simulator /></div></>;
}

export function AIPage() {
  const status = useRemote(getStatus, 'ai-status', 90_000);
  return <><SectionTitle eyebrow="INTELIGENCIA ARTIFICIAL" title="Informes de IA" description="Análisis automatizado trazable a datos y fuentes confirmadas." /><Panel title="Disponibilidad"><div className="feature-status"><div className="feature-icon"><Bot size={28} /></div><div><h2>{status.data?.ai?.enabled ? 'Servicio configurado' : 'Disponible en una fase posterior'}</h2><p>{status.data?.ai?.enabled ? `Estado comunicado por el servidor: ${status.data.ai.status}.` : 'La generación de informes por IA está desactivada en esta fase. Los directorios, mercados y datos históricos siguen disponibles.'}</p><Badge tone={status.data?.ai?.enabled ? 'good' : 'warn'}>{status.data?.ai?.status ?? 'Sin estado'}</Badge></div></div></Panel><div className="feature-grid"><div><BarChart3 size={20} /><strong>Análisis económico</strong><span>Informes basados en capturas verificadas.</span></div><div><Crosshair size={20} /><strong>Seguimiento militar</strong><span>Contexto de conflictos con fuentes citadas.</span></div><div><Newspaper size={20} /><strong>Prensa y acontecimientos</strong><span>Resumen de artículos con atribución.</span></div></div></>;
}

export function AlertsPage() {
  const [filter, setFilter] = useState<'all' | 'favorites'>('all');
  const [favorites, setFavorites] = useState(readFavorites);
  const remote = useRemote(() => getCollection('/api/alerts', new URLSearchParams({ page: '1', limit: '50', sort: 'updated_at', order: 'desc' })), 'alerts', 90_000);
  const toggle = (id: string) => { const next = favorites.includes(id) ? favorites.filter(item => item !== id) : [...favorites, id]; setFavorites(next); saveFavorites(next); };
  const rows = (remote.data?.items ?? []).filter(row => filter === 'all' || favorites.includes(text(row.id)));
  return <><SectionTitle eyebrow="MONITORIZACIÓN" title="Alertas" description="Eventos observados y favoritos guardados en este navegador." action={<button className="btn" onClick={remote.reload}><RefreshCw size={15} /> Actualizar</button>} /><div className="segmented"><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>Todas</button><button className={filter === 'favorites' ? 'active' : ''} onClick={() => setFilter('favorites')}><Bell size={14} /> Favoritas ({favorites.length})</button></div><Panel title="Centro de alertas" action={<SourceMeta source={remote.data?.source} />}>{remote.error && <ErrorState error={remote.error} onRetry={remote.reload} hasData={!!remote.data} />}{remote.loading && !remote.data ? <Loading /> : rows.length ? <div className="alert-list">{rows.map(row => <div key={text(row.id)} className="alert-row"><span className="alert-marker" /><div><Link to={`/alertas/${encodeURIComponent(text(row.id))}`}>{displayName(row)}</Link><p>{text(normalizedData(row).description ?? row.description, 'Alerta registrada; abre la ficha para consultar sus datos.')}</p><small>{date(row.updated_at)} · {age(row.updated_at)}</small></div><FavoriteButton selected={favorites.includes(text(row.id))} onClick={() => toggle(text(row.id))} /></div>)}</div> : remote.data ? <Empty title={filter === 'favorites' ? 'Sin favoritos guardados' : 'Sin alertas capturadas'} detail={filter === 'favorites' ? 'Marca una alerta con la estrella para guardarla aquí.' : 'El motor mostrará alertas cuando detecte cambios respaldados por datos reales.'} /> : null}</Panel><p className="footnote">Los favoritos se guardan solo en este navegador. Las alertas reflejan los datos disponibles, no una cobertura exhaustiva de WarEra.</p></>;
}

export function StatusPage() {
  const remote = useRemote(getStatus, 'status-page', 90_000);
  return <><SectionTitle eyebrow="OBSERVABILIDAD" title="Estado de datos" description="Salud de las fuentes, hora de última captura y volumen almacenado." action={<button className="btn" onClick={remote.reload} disabled={remote.refreshing}><RefreshCw size={15} className={remote.refreshing ? 'spin' : ''} /> Actualizar</button>} />{remote.error && <ErrorState error={remote.error} onRetry={remote.reload} hasData={!!remote.data} />}{remote.loading && !remote.data ? <Loading /> : remote.data && <><div className="metric-grid"><Metric label="Fuentes registradas" value={number(remote.data.sources.length)} icon={<Database size={16} />} /><Metric label="Sincronizadas" value={number(remote.data.sources.filter(x => sourceState(x).tone === 'good').length)} icon={<Check size={16} />} /><Metric label="Con incidencias" value={number(remote.data.sources.filter(x => sourceState(x).tone === 'bad').length)} icon={<Activity size={16} />} /><Metric label="Última respuesta" value={age(remote.data.timestamp)} icon={<Clock3 size={16} />} /></div><Panel title="Fuentes de datos">{remote.data.sources.length ? <div className="sources-list">{remote.data.sources.map(source => <div key={source.id} className="source-detail"><div className="source-detail-head"><strong>{source.id}</strong><Badge tone={sourceState(source).tone}>{sourceState(source).label}</Badge></div><div className="source-detail-grid"><span>Último éxito<strong>{date(source.last_success)}</strong></span><span>Último intento<strong>{date(source.last_attempt)}</strong></span><span>Intervalo<strong>{source.interval_seconds ? `${number(source.interval_seconds / 60, 1)} min` : '—'}</strong></span><span>Registros<strong>{number(source.record_count)}</strong></span></div>{source.last_error && <div className="source-error">{source.last_error}</div>}{safeUrl(source.endpoint) && <a className="source-link" href={safeUrl(source.endpoint)!} target="_blank" rel="noopener noreferrer">Endpoint público <ExternalLink size={12} /></a>}</div>)}</div> : <Empty detail="El registro de fuentes todavía está vacío." />}</Panel><Panel title="Registros almacenados"><div className="totals-grid">{Object.entries(remote.data.totals ?? {}).map(([key, value]) => <div key={key}><span>{key.replaceAll('_', ' ')}</span><strong>{number(value)}</strong></div>)}</div></Panel></>}</>;
}

type AdminRun = { id: string; source_id?: string; started_at?: string; finished_at?: string; status?: string; records_count?: number; duration_ms?: number; error?: string | null };
type AdminQuota = { dailyBudget?: number; reserved?: number; remaining?: number; day?: string; estimate?: boolean };
type AdminWriteUsage = { source_id: string; mode: string; runs: number; ok_runs: number; failed_runs: number; records: number; measured_writes: number | null; reserved_writes: number | null; writes_per_record: number | null };
type AdminStatus = Status & { authenticated?: boolean; configured?: boolean; runs?: AdminRun[]; quota?: AdminQuota; operations?: OperationsHealth; writeUsage?: { day: string; bySource: AdminWriteUsage[] } };
type SyncOutcome = { status: 'ok' | 'error' | 'quota-paused' | 'busy' | 'idle' | 'unknown-source'; source?: string; processed?: number; changed?: number; nextRunAt?: string; error?: string };
type ImportPreview = { resource?: string; records?: Record<string, unknown>[]; preview?: Record<string, unknown>[]; errors?: string[]; warnings?: string[]; duplicates?: number; valid?: number | boolean; total?: number; [key: string]: unknown };

export function AdminPage() {
  const [session, setSession] = useState<'checking' | 'in' | 'out' | 'unconfigured'>('checking');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [admin, setAdmin] = useState<AdminStatus | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<ImportPreview | null>(null);
  const [resource, setResource] = useState<'players' | 'parties' | 'military-units'>('players');
  const refresh = async () => {
    try { const value = await request<AdminStatus>('/api/admin/status'); setAdmin(value); setSession(value.configured === false ? 'unconfigured' : value.authenticated === false ? 'out' : 'in'); }
    catch (error) { setSession(error instanceof Error && 'status' in error && (error as { status: number }).status === 503 ? 'unconfigured' : 'out'); }
  };
  useEffect(() => { void refresh(); }, []);
  const login = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setMessage(''); try { await adminRequest('/api/admin/login', 'POST', { password }); setPassword(''); await refresh(); } catch (error) { if (error instanceof Error && 'status' in error && (error as { status: number }).status === 503) setSession('unconfigured'); setMessage(error instanceof Error ? error.message : 'No se pudo iniciar sesión.'); } finally { setBusy(false); } };
  const logout = async () => { setBusy(true); try { await adminRequest('/api/admin/logout', 'POST'); setSession('out'); setAdmin(null); setMessage('Sesión cerrada.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'No se pudo cerrar sesión.'); } finally { setBusy(false); } };
  const sync = async (source?: string) => { setBusy(true); setMessage(''); try { const result = await adminRequest<SyncOutcome>('/api/admin/sync', 'POST', source ? { source } : {}); const label = result.source ?? source ?? 'las fuentes'; if (result.status === 'ok') setMessage(`Sincronización completada en ${label}: ${number(result.processed)} registros procesados y ${number(result.changed)} cambios.`); else if (result.status === 'error') setMessage(`Error al sincronizar ${label}: ${result.error ?? 'consulta fallida'}.`); else if (result.status === 'quota-paused') setMessage(`Sincronización aplazada por cuota en ${label}${result.nextRunAt ? ` hasta ${date(result.nextRunAt)}` : ''}.`); else if (result.status === 'busy') setMessage(`La fuente ${label} ya está sincronizándose.`); else if (result.status === 'idle') setMessage('No hay fuentes activas pendientes de sincronización.'); else setMessage(`Fuente desconocida: ${label}.`); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'No se pudo iniciar la sincronización.'); } finally { setBusy(false); } };
  const updateSource = async (source: Source, patch: { enabled?: boolean; interval_seconds?: number }) => { setBusy(true); setMessage(''); try { await adminRequest(`/api/admin/sources/${encodeURIComponent(source.id)}`, 'PATCH', patch); setMessage(`Fuente ${source.id} actualizada.`); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'No se pudo actualizar la fuente.'); } finally { setBusy(false); } };
  const previewFile = async () => { if (!file) return; setBusy(true); setMessage(''); setPreview(null); try { const form = new FormData(); form.append('file', file); form.append('resource', resource); const value = await request<ImportPreview>('/api/admin/import/preview', { method: 'POST', headers: { 'X-WINT-CSRF': '1' }, body: form }); setPreview(value); } catch (error) { setMessage(error instanceof Error ? error.message : 'No se pudo previsualizar el archivo.'); } finally { setBusy(false); } };
  const commitImport = async () => { const records = preview?.records ?? preview?.preview; if (!records?.length || preview?.valid === false || preview?.errors?.length) return; setBusy(true); setMessage(''); try { let inserted = 0; let skipped = 0; for (let offset = 0; offset < records.length; offset += 10) { const result = await adminRequest<{ inserted?: number; skipped?: number }>('/api/admin/import', 'POST', { resource, records: records.slice(offset, offset + 10) }); inserted += result.inserted ?? 0; skipped += result.skipped ?? 0; } setMessage(`Importación completada: ${inserted} incorporados, ${skipped} omitidos de ${records.length} registros.`); setPreview(null); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'No se pudo completar la importación.'); } finally { setBusy(false); } };
  return <><SectionTitle eyebrow="ACCESO RESTRINGIDO" title="Administración" description="Control de fuentes, sincronización e importación de datos." action={session === 'in' && <button className="btn" onClick={logout} disabled={busy}>Cerrar sesión</button>} />
    {session === 'checking' ? <Loading label="Comprobando sesión administrativa…" /> : session === 'unconfigured' ? <Panel title="Configuración pendiente"><div className="feature-status"><LockKeyhole size={27} /><p>El servidor no tiene configuradas las credenciales administrativas. Configura los secretos del Worker y vuelve a cargar esta página.</p></div></Panel> : session === 'out' ? <Panel title="Iniciar sesión" className="login-panel"><form onSubmit={login} className="login-form"><div className="login-icon"><LockKeyhole size={25} /></div><p>Introduce la contraseña de administración configurada en el servidor.</p><label className="form-field"><span>Contraseña</span><input type="password" required autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)} /></label><button type="submit" className="btn primary" disabled={busy}>{busy ? 'Verificando…' : 'Entrar al panel'}</button>{message && <div className="form-message">{message}</div>}</form></Panel> : <>
      {message && <div className="notice info"><Info size={17} />{message}</div>}
      <div className="metric-grid"><Metric label="Fuentes" value={number(admin?.sources.length)} icon={<Database size={16} />} /><Metric label="Errores activos" value={number(admin?.sources.filter(x => !!x.last_error).length)} icon={<Activity size={16} />} /><Metric label="IA" value={admin?.ai?.status ?? 'Desactivada'} icon={<Bot size={16} />} /><Metric label="Respuesta de API" value={age(admin?.timestamp)} icon={<Clock3 size={16} />} /></div>
      {admin?.quota && <Panel title="Cuota de sincronización"><div className="totals-grid"><div><span>Presupuesto diario</span><strong>{number(admin.quota.dailyBudget)}</strong></div><div><span>Reserva</span><strong>{number(admin.quota.reserved)}</strong></div><div><span>Disponible</span><strong>{number(admin.quota.remaining)}</strong></div><div><span>Día</span><strong>{text(admin.quota.day)}</strong></div></div>{admin.quota.estimate && <p className="panel-description">Escrituras registradas por D1 más un margen de seguridad. Las reservas antiguas o de ejecuciones fallidas se conservan; este contador no incluye otros proyectos de la cuenta.</p>}</Panel>}
      <Panel title="Sincronización y fuentes" action={<button className="btn" disabled={busy} onClick={() => sync()}><RefreshCw size={15} /> Sincronizar ahora</button>}>{admin?.sources.length ? <div className="admin-sources">{admin.sources.map(source => <AdminSourceRow key={source.id} source={source} busy={busy} onSave={patch => updateSource(source, patch)} onSync={() => sync(source.id)} />)}</div> : <Empty detail="No hay fuentes configuradas en el registro." />}</Panel>
      {admin?.operations && admin.operations.messages.length > 0 && <div className={`notice ${admin.operations.level === 'ok' ? '' : 'warn'}`} role={admin.operations.level === 'bad' ? 'alert' : 'status'}><Info size={16} aria-hidden="true" /><span><strong>{admin.operations.level === 'bad' ? 'Atención: recopilación degradada.' : admin.operations.level === 'warn' ? 'Revisa la recopilación.' : 'Recopilación.'}</strong> {admin.operations.messages.join(' ')} Último commit del recolector: {date(admin.operations.lastCollectorCommitAt)}.</span></div>}
      <Panel title="Escrituras de hoy por fuente">{admin?.writeUsage?.bySource.length ? <div className="table-scroll" tabIndex={0} role="region" aria-label="Tabla desplazable"><table className="data-table"><caption>Día UTC {admin.writeUsage.day}. Las ejecuciones sin liquidar conservan su reserva completa.</caption><thead><tr><th>Fuente</th><th>Modo</th><th>Ejecuciones</th><th>Fallidas</th><th>Registros</th><th>Escrituras medidas</th><th>Por registro</th></tr></thead><tbody>{admin.writeUsage.bySource.map(row => <tr key={`${row.source_id}:${row.mode}`}><td>{text(row.source_id)}</td><td>{row.mode === 'compact' ? 'Recolector' : row.mode === 'direct' ? 'Cron' : row.mode === 'paused' ? 'Pausada por cuota' : 'Sin liquidar'}</td><td>{number(row.runs)}</td><td>{number(row.failed_runs)}</td><td>{number(row.records)}</td><td>{number(row.measured_writes)}</td><td>{row.writes_per_record ?? '—'}</td></tr>)}</tbody></table></div> : <Empty detail="Sin ejecuciones medidas hoy (UTC)." />}</Panel>
      <Panel title="Últimas sincronizaciones">{admin?.runs?.length ? <div className="table-scroll" tabIndex={0} role="region" aria-label="Tabla desplazable"><table className="data-table"><thead><tr><th>Fuente</th><th>Inicio</th><th>Estado</th><th>Registros</th><th>Duración</th><th>Error</th></tr></thead><tbody>{admin.runs.slice(0, 20).map(run => <tr key={run.id}><td>{text(run.source_id)}</td><td>{date(run.started_at)}</td><td><Badge tone={run.status === 'ok' ? 'good' : run.status === 'error' ? 'bad' : 'warn'}>{text(run.status)}</Badge></td><td>{number(run.records_count)}</td><td>{run.duration_ms === null || run.duration_ms === undefined ? '—' : `${number(run.duration_ms)} ms`}</td><td title={run.error ?? undefined}>{text(run.error)}</td></tr>)}</tbody></table></div> : <Empty detail="Todavía no hay ejecuciones registradas." />}</Panel>
      <CoveragePanel /><Panel title="Importar archivos públicos"><p className="panel-description">Previsualiza CSV, JSON o ZIP antes de incorporarlos a WINT. El servidor valida y normaliza los registros.</p><div className="import-controls"><label className="form-field"><span>Tipo de registros</span><select value={resource} onChange={event => { setResource(event.target.value as typeof resource); setPreview(null); }}><option value="players">Jugadores</option><option value="parties">Partidos</option><option value="military-units">Unidades militares</option></select></label><label className="form-field"><span>Archivo</span><input type="file" accept=".csv,.json,.zip,application/json,text/csv,application/zip" onChange={event => { setFile(event.target.files?.[0] ?? null); setPreview(null); }} /></label><button className="btn" disabled={!file || busy} onClick={previewFile}><Upload size={15} /> Previsualizar</button></div>{preview && <div className="preview-block"><h3>Previsualización</h3><p>{preview.valid === false ? 'Archivo no válido.' : `${number(typeof preview.valid === 'number' ? preview.valid : preview.records?.length ?? preview.preview?.length ?? 0)} registros válidos de ${number(preview.total ?? preview.records?.length ?? preview.preview?.length ?? 0)} detectados.`}{preview.duplicates ? ` ${preview.duplicates} duplicados.` : ''}</p>{(preview.errors ?? []).map((item, index) => <div className="source-error" key={index}>{item}</div>)}{(preview.warnings ?? []).map((item, index) => <div className="preview-warning" key={index}>{item}</div>)}{(preview.records ?? preview.preview ?? []).slice(0, 5).map((row, index) => <pre key={index}>{JSON.stringify(row, null, 2)}</pre>)}<button className="btn primary" disabled={busy || !(preview.records?.length || preview.preview?.length) || preview.valid === false || !!preview.errors?.length} onClick={commitImport}>Importar registros validados</button></div>}</Panel>
      <Notice>Los intervalos y la disponibilidad de IA dependen de la configuración del Worker y las cuotas del plan desplegado.</Notice>
    </>}
  </>;
}

function AdminSourceRow({ source, busy, onSave, onSync }: { source: Source; busy: boolean; onSave: (patch: { enabled?: boolean; interval_seconds?: number }) => void; onSync: () => void }) {
  const [enabled, setEnabled] = useState(source.enabled !== false && source.enabled !== 0);
  const [minutes, setMinutes] = useState(Math.max(2, Math.round((source.interval_seconds ?? 3600) / 60)));
  useEffect(() => { setEnabled(source.enabled !== false && source.enabled !== 0); setMinutes(Math.max(2, Math.round((source.interval_seconds ?? 3600) / 60))); }, [source.enabled, source.interval_seconds]);
  return <div className="admin-source-row"><div><strong>{source.id}</strong><small>Último éxito: {date(source.last_success)}</small>{source.last_error && <small className="negative">{source.last_error}</small>}</div><Badge tone={sourceState(source).tone}>{sourceState(source).label}</Badge><label className="switch-label"><input type="checkbox" checked={enabled} onChange={event => setEnabled(event.target.checked)} /> Activa</label><label className="minutes-label"><input type="number" min="2" max="1440" value={minutes} onChange={event => setMinutes(Number(event.target.value))} /> min</label><div className="admin-source-actions"><button className="btn small" disabled={busy || minutes < 2 || minutes > 1440} onClick={() => onSave({ enabled, interval_seconds: minutes * 60 })}>Guardar</button><button className="icon-btn" disabled={busy} onClick={onSync} aria-label={`Sincronizar ${source.id}`} title="Sincronizar"><RefreshCw size={15} /></button></div></div>;
}

export function NotFound() { return <><SectionTitle eyebrow="NAVEGACIÓN" title="Página no encontrada" description="La ruta solicitada no existe en WINT." /><Link to="/" className="btn primary"><ArrowLeft size={15} /> Volver al centro de mando</Link></>; }
